"""Original concept decisions; targets are hypotheses, never product ratings."""
COMMON_SENSORS=['Advisory position / wear sensing with replaceable brackets; no AI-controlled brake release.', 'Record supplier sensor range, supply, connector, EMC, ingress and temperature limits before selection.', 'Define independent machine safety interface and diagnostic fault response with the responsible controls engineer.']
BRIEFS={
'AB-ROT':dict(slug='rotating-components',short='Discs & hubs',subtitle='The common rotating interface',level='Mechanical concept',priority=1,description='A 400 mm disc and detachable flanged hub define a shared prototype interface. The drum variant appears in the drum-brake package. This is a geometry study, not a speed-rated rotor.',targets=[['Disc outside diameter','400 mm','Modelled geometry'],['Disc thickness','20 mm','Modelled geometry'],['Hub shaft bore','50 mm','Illustrative shaft interface'],['Mounting pattern','6 × Ø13 on PCD 150 mm','Modelled; M12 candidate'],['Torque / speed rating','Not assigned','Shaft, balance and thermal assessment required']],decisions=['Use a detachable hub to replace the friction disc without replacing the shaft interface.','Begin with machined steel for prototype traceability; evaluate a cast-iron friction variant only through paired friction and thermal tests.','Use one six-hole interface across the first disc concepts; bolt preload and joint slip capacity remain to be sized.'],materials=['Disc: C45 normalized steel candidate; friction compound must be qualified with this surface.','Hub: 42CrMo4 quenched-and-tempered candidate; property certificate must correspond to actual section size.'],risks=['Disc-to-hub torque transfer, bolt preload and fatigue are not yet established.','No keyway or locking element is released; the 50 mm bore is an interface placeholder.','Thermal coning, hot runout, balance and overspeed remain unverified.'],steps=['Inspect disc and hub identification, bore and interface faces.','Locate disc on the hub spigot; align six through holes.','Fit the specified through-bolts, washers and nuts after joint design is approved.','Measure assembled runout and balance before guarded testing.'],validation=['Thermal transient model with moving pad heat flux and measured heat partition.','Bolted joint slip, bearing, hub torsion and rotational stress calculations.','Guarded speed, runout, balance and repeated stop tests.'],hypotheses=[['Service time','25% reduction target','Time disc replacement versus a documented integral-hub baseline with the same shaft access.'],['Commonality','One disc/hub pattern','Count unique components across the disc-brake concepts; this is not a competitor advantage claim.']],sensors=['Reserve non-contact runout measurement access and a temperature observation window.']),
'AB-DR':dict(slug='drum-brake',short='Drum brake',subtitle='The first service-brake platform',level='Kinematic layout',priority=2,description='A spring-applied, thruster-released 315 mm drum concept with replaceable shoes, accessible pivots and a fabricated base. DIN compatibility is a future interface check, not claimed by this geometry.',targets=[['Drum diameter','315 mm','Modelled geometry'],['Friction width','100 mm','Modelled geometry'],['Study holding torque','500 N·m','Unverified requirements hypothesis'],['Assumed minimum friction','0.30','Sensitivity input, not lining data'],['Required total shoe normal force','10.58 kN','T / (μr); excludes self-energization']],decisions=['Buy a qualified thruster first; put development effort into accessible metalwork and service interfaces.','Keep pivot pins and bushes separately replaceable rather than boring directly into welded levers.','Use a fabricated prototype base; casting economics follow actual batch volumes.'],materials=['Base and lever plate: S355J2+N candidate; weld procedure and fatigue detail approval required.','Pins: 42CrMo4 candidate with controlled finish; bushes: purchased bearing-grade bronze candidate.','Lining: bought, characterized non-asbestos compound; bonding and mechanical retention require supplier approval.'],risks=['Equalization, spring linkage and actuator transmission are layout placeholders; motion is not solved.','The assumed torque is not a rating and does not cover an emergency stop or hoist safety case.','Shoe contact geometry, drum heating and pivot loads require coupled assessment.'],steps=['Locate base on the test fixture and inspect pivot-centre coordinates.','Fit clevis supports, levers, bushes and retained pivot pins.','Install carriers and lining; centre the drum and establish cold clearance.','Install purchased thruster and engineered equalizing/spring linkage after kinematic approval.','Check full release motion without friction contact before load testing.'],validation=['Kinematic travel/clearance and load transfer before structural FEA.','Lever/pin bearing, bending, base weld fatigue and drum thermal calculations.','Static holding, dynamic torque, application/release time and endurance tests with the chosen lining.'],hypotheses=[['Shoe service time','20% reduction target','Timed same-duty shoe replacement against a selected conventional assembly.'],['Supplier lead time','To be measured','Compare two quotes for plate fabrication with equivalent cast components.']],sensors=COMMON_SENSORS),
'AB-DC':dict(slug='disc-caliper',short='Disc caliper',subtitle='A shared spring-applied platform',level='Mechanical layout',priority=3,description='A fixed opposed-pad bridge concept around the common 400 mm disc. A purchased spring-applied hydraulic-release cartridge is represented by its envelope; its internal mechanism is not designed here.',targets=[['Disc diameter / thickness','400 / 20 mm','Shared geometry'],['Pad planform','70 × 60 mm','Concept area before corner / retention detail'],['Study torque','1,000 N·m','Unverified requirements hypothesis'],['Effective radius','155 mm','Uniform-pressure rectangular-pad approximation'],['Normal force per face','10.75 kN','T / (2μr), μ = 0.30']],decisions=['A fixed bridge establishes a direct load path; removable pad retainers are a serviceability hypothesis.','Use a bought release cartridge for the first test rig rather than developing seals and spring stacks simultaneously.','Share the rotor/hub pattern with the positive-actuated brake study.'],materials=['Bridge and cheeks: S355J2+N plate for prototype; machined critical faces after fabrication.','Pad backing: C45 steel candidate, with purchased qualified lining.','Tie fasteners: purchased certified fasteners; grade, preload and locking method unresolved.'],risks=['Bridge deflection, pad pressure distribution and hot clearance are not verified.','Cartridge load path and equalization are interface requirements, not functional geometry.','Pressure, spring force and release stroke must come from the selected supplier.'],steps=['Locate bridge and cheek plates with interface holes aligned.','Install replaceable backing plates, lining and retainer pins.','Mount supplier-approved actuator cartridges on the outer interfaces.','Centre rotor in the cold gap; verify hot-growth allowance analytically.','Approve joint preload, retainer security and release stroke before guarded testing.'],validation=['Contact/nonlinear bridge FEA with supplier actuator loads.','Thermal distortion, wear travel and worst-case tolerance stack.','Torque versus pressure/release state, pad change, leakage and endurance tests.'],hypotheses=[['Pad replacement','30% less hands-on time target','Timed pad change with matched guarding and access.'],['Prototype variants','One rotor interface','Demonstrate common disc and hub across two actuation variants.']],sensors=COMMON_SENSORS),
'AB-SP':dict(slug='service-kits',short='Service kits',subtitle='Parts that keep the platform serviceable',level='Mechanical concept',priority=4,description='An identifiable caliper service set: backing plates, lining blocks, retainer pins and bushes. It is scoped to AI Braking concepts; no fit or compatibility with a competitor brake is implied.',targets=[['Pad footprint','70 × 60 mm','Shared with AB-DC'],['Lining concept thickness','8 mm','Wear allowance unapproved'],['Retainer pin diameter','8 mm','Nominal concept'],['Traceability','100% kits linked to parent revision','Process objective, not achieved factory evidence']],decisions=['Separate wear parts from structural parts in the BOM and drawing numbering.','Source the friction compound and its retention process from a specialist.','Mark non-friction backing surfaces, avoiding stress-sensitive and rubbing surfaces.'],materials=['Backing plate: C45 candidate, corrosion protection excluded from bond/friction areas.','Lining: supplier-controlled non-asbestos compound, not a generic material grade.','Pins/bushes: certified steel and purchased bronze candidates.'],risks=['Friction coefficient changes with pressure, speed, temperature and wear.','Bond strength, rivet design, retainer fatigue and wear limits are not specified.'],steps=['Verify parent brake revision and compound lot.','Inspect backing plate and clean bond surfaces using supplier process.','Bond/retain lining only to an approved supplier procedure.','Install pins and bushes with the engineer-approved fit and retention.'],validation=['Bond/retention strength, dimensional fit and compound lot consistency.','Paired dynamometer testing of fade, recovery and wear.'],hypotheses=[['Identification errors','Zero wrong-revision installations target','Test scanning and human-readable part identification in service trials.'],['Service inventory','Shared kit target','Confirm common parts without extending compatibility beyond released drawings.']],sensors=['Record digital part/lot identity and wear measurement requirements; sensor design deferred.']),
'AB-AIST':dict(slug='mill-duty-brake',short='Mill-duty brake',subtitle='An export interface study',level='Kinematic layout',priority=8,description='A 12-inch drum layout explores a mill-duty envelope using the same modelling primitives. No AISE/AIST interchangeability, duty classification or compliance is asserted.',targets=[['Drum diameter','304.8 mm / 12 in','Study geometry'],['Shoe width','100 mm','Not a standard interface'],['Study holding torque','500 N·m','Hypothesis; duty not received'],['Mounting pattern','Unreleased','Customer interface drawing required']],decisions=['Keep a separate interface family instead of relabelling the DIN-oriented concept.','Buy actuation until the severe-duty force/time envelope is known.','Prioritize access for inspection and replacement in dirty environments.'],materials=['S355J2+N candidate structure with environment-specific coating.','Rotor and lining pair require mill-duty temperature and contamination assessment.'],risks=['All mounting dimensions are original placeholders, not an AIST drawing.','High cycle duty, hot surroundings and corrosion require a separate load spectrum.'],steps=['Obtain machine interface dimensions and applicable standard revision.','Review base, pivot and thruster positions against that interface.','Proceed with the drum-platform assembly sequence only after separate design approval.'],validation=['Interface metrology and full duty-cycle definition.','Contaminated/environmental endurance and thermal testing.'],hypotheses=[['Maintenance access','20% faster inspection target','Timed inspection against the customer’s installed mill brake.'],['Reuse','Shared non-interface components','Measure actual reuse after duty loads are approved.']],sensors=COMMON_SENSORS),
'AB-ACT':dict(slug='thruster-interface',short='Thruster integration',subtitle='Buy the actuator. Engineer the interface.',level='Purchased envelope',priority=7,description='A mounting cradle and simplified thruster envelope support early integration. The motor, pump, piston and seal internals are deliberately not released as manufacturable designs.',targets=[['Illustrative stroke','60 mm','Envelope assumption'],['Illustrative release force','2 kN','RFQ starting point, not supplier selection'],['Body envelope','Ø120 × 240 mm','Placeholder'],['Electrical supply / duty','To be specified','Requirements only']],decisions=['Buy an industrial thruster for the first brake prototypes.','Keep mounting clevises replaceable to adapt to the selected supplier drawing.','Separate thrust, stroke and time requirements; one cannot substitute for another.'],materials=['Cradle: S355J2+N candidate fabricated plate.','Thruster body and rod: supplier-controlled; CAD volumes are reserved space only.'],risks=['Force requirement cannot be finalized until the brake linkage is solved.','No internal hydraulic/electrical design, pressure rating or environmental certification.'],steps=['Select supplier using force-stroke-time-temperature data.','Replace envelope with supplier STEP and approved pin dimensions.','Fit cradle and retained pivots; inspect alignment across full stroke.'],validation=['Supplier documentation review and incoming force/stroke/time tests.','Side-load, mounting fatigue, seal leakage and temperature tests.'],hypotheses=[['Development scope','Avoid internal actuator development initially','Compare integration effort with a quoted custom-thruster programme.'],['Service replacement','One removable cradle','Verify access without dismantling the brake frame.']],sensors=['Specify motor voltage/frequency, duty cycle, insulation, cable entry, ingress, thermal protection and end-state sensing.']),
'AB-HPU':dict(slug='hydraulic-power-unit',short='Hydraulic power unit',subtitle='A serviceable hydraulic integration deck',level='Integration layout',priority=6,description='A compact reservoir and removable equipment deck reserve space for a bought motor-pump, valve manifold and filtration. This is packaging CAD, not a designed hydraulic circuit.',targets=[['Reservoir outside envelope','400 × 260 × 220 mm','Geometry'],['Gross internal volume','≈21.5 L','Unbaffled volume; usable oil level unassigned'],['System pressure / flow','Unassigned','Derive from selected caliper and release timing'],['Circuit architecture','Pending safety analysis','No pressure-retaining custom manifold design']],decisions=['Buy qualified hydraulic components and manifold rather than machine custom pressure passages.','Use a removable deck for bench service and clearly separated fill/drain access.','Allocate pressure sensing and filtered breather space early; select hardware after the circuit review.'],materials=['Reservoir: S355J2+N candidate welded sheet; cleanliness and coating compatibility require review.','Pump, motor, valve block and filter: purchased certified components.'],risks=['No circuit, relief setting, accumulator sizing or failure-state analysis is completed.','Reserved component volumes are not vendor dimensions.','Reservoir baffles, suction conditions and thermal dissipation remain unresolved.'],steps=['Approve circuit and equipment list before cutting sheet.','Fabricate and leak-test reservoir to approved welding and cleaning procedure.','Install removable deck and selected component brackets.','Fit piping, flushing, relief protection and controls per approved hydraulic schematic.'],validation=['Circuit failure analysis, pressure transients, oil temperature and cleanliness.','Leak, flush, loss-of-power and repeated application/release tests.'],hypotheses=[['Bench service','25% less disassembly time target','Compare equipment access against a fixed-deck baseline.'],['Procurement','Bought pressure components','Compare qualified vendor quotations, not assumed unit costs.']],sensors=['Define pressure transducer, oil level/temperature, filter clog switch, motor starter, E-stop interaction and independent safe valve state.']),
'AB-COUP':dict(slug='coupling-interface',short='Coupling interface',subtitle='A modular drive-train connection',level='Interface concept',priority=9,description='Two flanged hubs and a spacer envelope explore a bought flexible element. Tooth forms and elastomer geometry are not designed, so this is not a working gear or flexible coupling.',targets=[['Illustrative shaft bores','50 mm','Unreleased shaft fit'],['Hub flange diameter','160 mm','Concept geometry'],['Six-hole pattern','PCD 120 mm, Ø11','M10 candidate'],['Torque / misalignment / speed','Unassigned','Supplier and shaft-system study required']],decisions=['Buy the flexible element or full coupling for the first prototypes.','Keep hub removal and brake-disc access visible in the packaging study.','Treat torsional resonance and misalignment separately from static torque.'],materials=['Hubs: 42CrMo4 candidate, condition to be selected for section and fatigue.','Flexible element: vendor-controlled compound or gear assembly.'],risks=['No transmitting connection between the placeholder flexible element and hubs is released.','No keyway, shaft fit, balancing or retention design.'],steps=['Approve shaft and torsional system requirements.','Replace spacer with qualified supplier geometry.','Finalize hub attachment, alignment and guarding before prototype assembly.'],validation=['Shaft torsion, key/locking connection, fatigue and critical-speed assessment.','Supplier torque/misalignment endurance and balance confirmation.'],hypotheses=[['Access','Hub removal without rotor damage target','Validate on a physical installation mock-up.'],['Schedule','Buy before custom gear development','Compare quoted full-coupling integration against a custom programme.']],sensors=['Reserve guard clearance and optional vibration/speed monitoring; no sensors in rotating masses.']),
'AB-POS':dict(slug='positive-actuated-brake',short='Positive-actuated brake',subtitle='The common caliper, different behaviour',level='Mechanical layout',priority=10,description='A direct-applied cartridge variant of the disc concept for controlled process braking. Loss of actuation releases braking force; it does not inherit spring-applied holding behaviour.',targets=[['Rotor interface','400 × 20 mm','Shared AB-ROT geometry'],['Study torque','500 N·m','Process-brake hypothesis'],['Normal force per face','5.38 kN','At μ=0.30, r=155 mm'],['Loss of pressure','Brake force lost','Must be acceptable to the machine safety concept']],decisions=['Reuse the rotor and selected metalwork only after confirming actuator loads.','Keep the operating principle explicit to prevent selection as a default holding brake.','Buy direct-actuation cylinders and define modulation requirements separately.'],materials=['Shared concept bridge/pad materials with AB-DC.','Direct actuator: supplier-selected seals, body and piston materials.'],risks=['Not a fail-safe holding brake.','No modulation loop, thermal-duty capability or emergency-stop approval.'],steps=['Confirm application permits loss of braking on loss of supply.','Assemble shared caliper metalwork and supplier direct actuators.','Set pressure limiting and independent protection after system review.'],validation=['Pressure-force/torque curve, hysteresis and response.','Thermal duty and loss-of-supply behaviour.'],hypotheses=[['Commonality','Shared rotor / hub goal','Measure released BOM reuse with AB-DC.'],['Control quality','No numerical claim','Measure torque tracking after actuator and controller selection.']],sensors=COMMON_SENSORS),
'AB-BUF':dict(slug='buffer-module',short='Buffer module',subtitle='An absorber integration, not a brake',level='Purchased envelope',priority=11,description='A replaceable purchased energy absorber, bumper face and bolted mounting plate for a later crane end-stop programme. Absorber internals and force-stroke characteristics are not designed.',targets=[['Study impact energy','5 kJ','Illustrative requirements input'],['Illustrative stroke','150 mm','Reserved travel'],['Average stopping force','33.3 kN','E / s only; peak force unknown'],['Supplier rating','Unassigned','Impact mass, speed and duty required']],decisions=['Partner with an absorber specialist rather than infer impact qualification from brake work.','Use a replaceable mounting interface and visible stroke envelope.','Size the machine attachment for verified peak force, not E/s average.'],materials=['Mounting plate: S355J2+N candidate.','Absorber and bumper face: supplier-controlled hydraulic/elastomer components.'],risks=['No metering geometry, damping curve or peak force established.','Travel envelope does not demonstrate energy absorption.'],steps=['Collect impact mass, speed, available stroke and recovery interval.','Select rated absorber and replace CAD envelope with supplier model.','Approve foundation fasteners and collision clearance.'],validation=['Supplier force-stroke curve and machine structure analysis.','Instrumented impact, temperature and repeated-impact tests.'],hypotheses=[['Replacement time','20% reduction target','Compare removable cartridge service with the customer baseline.'],['Verification','Measured peak-force requirement','No performance multiple assigned before impact testing.']],sensors=['Stroke/end-position and impact-event recording only; define survival environment and cable protection.']),
'AB-SPEC':dict(slug='rail-clamp-study',short='Rail clamp study',subtitle='A separate storm-holding programme',level='Interface concept',priority=12,description='A rail-head clamp packaging study with opposed shoes and an actuator envelope. Rail dimensions, wedge/spring mechanism and certified holding force require an application-specific design.',targets=[['Illustrative rail head','70 mm wide','Not a railway profile standard'],['Study holding force','20 kN','Hypothesis'],['Assumed wet friction','0.10','Sensitivity only; tests required'],['Normal force per shoe','100 kN','F / (2μ), excluding mechanisms']],decisions=['Require the actual rail profile and wind-load analysis before developing a clamp mechanism.','Partner with a specialist for first installations.','Keep contamination and rail surface variation central to the requirements.'],materials=['Frame: S355J2+N candidate only; loads may force a different section or material.','Rail shoes: supplier friction system; rail damage compatibility must be assessed.'],risks=['No functional wedge, latch or spring mechanism is modelled.','High required normal forces make this an application-specific structural programme.','No personnel-transport, storm safety or hazardous-area approval.'],steps=['Obtain rail profile, rail restraint, wind loads and failure-state requirements.','Approve specialist mechanism and dimensional interface.','Finalize clamps, foundation, guarding and independent verification.'],validation=['Wind load and machine/rail load path analysis.','Wet/oily rail holding tests, release clearance and fault testing.'],hypotheses=[['Inspection','Accessible wear surfaces target','Validate with a service mock-up.'],['Holding force','No improvement claim','Compare only tested units on the same rail, contamination and load case.']],sensors=COMMON_SENSORS),
'AB-MON':dict(slug='inspection-fixture',short='Inspection fixture',subtitle='Measure first. Let AI assist.',level='Fixture concept',priority=5,description='A non-safety bench fixture for checking a disc with bought supports and a movable indicator arm. It gives inspection a repeatable physical datum while electronics and AI stay at requirements level.',targets=[['Supported disc','400 mm concept','Packaging check'],['Runout study target','≤0.05 mm','Proposed requirement, not a part acceptance limit'],['Gauge resolution objective','≤0.005 mm','Ten-to-one study rule; full uncertainty needed'],['Acceptance authority','Calibrated measurement + approved plan','AI advisory only']],decisions=['Buy calibrated indicators and supports; fabricate the base and adjustable brackets.','Separate model anomaly detection from final dimensional acceptance.','Tie each reading to part, fixture, instrument, calibration and environmental records.'],materials=['Base: machined steel candidate; stiffness and stability require assessment.','Arms: aluminium 6082-T6 candidate; non-load-bearing metrology supports.','Indicators and centres: purchased calibrated equipment.'],risks=['No measurement-system analysis or uncertainty budget has been completed.','Fixture and datum errors can dominate small runout readings.'],steps=['Level and qualify the base and purchased centres.','Mount the rotor without distorting its datum surfaces.','Set a calibrated probe normal to the inspected face.','Record repeated rotations, remounts and operator variation before acceptance use.'],validation=['Gauge repeatability/reproducibility and uncertainty budget.','Comparison with calibrated reference artefacts and independent CMM measurement.'],hypotheses=[['Reporting effort','50% less transcription time target','Timed digital versus manual inspection report creation.'],['Acceptance quality','No accuracy improvement claim','Demonstrate uncertainty and false-alarm rates before use.']],sensors=['Define displacement range/resolution, triggering, sampling, DAQ, traceable calibration, environmental sensing, storage and human approval workflow.'])
}
